cssKeyframes.body:
@keyframes loader-spin { 
  0% { animation-timing-function: cubic-bezier(0.55, 0.055, 0.675, 0.19); transform: rotate(0deg); }
  50% { animation-timing-function: cubic-bezier(0.215, 0.61, 0.355, 1); transform: rotate(180deg); }
  100% { transform: rotate(1turn); }
}

@keyframes shake { 
  41%, 8% { transform: translateX(-10px); }
  25%, 58% { transform: translateX(10px); }
  75% { transform: translateX(-5px); }
  92% { transform: translateX(5px); }
  0%, 100% { transform: translateX(0px); }
}

@keyframes countdown-last-lift { 
  0% { transform: translateY(-100%); z-index: 0; }
  100% { transform: translateY(0px); z-index: 1; }
}

@keyframes countdown-last-flip { 
  0% { transform: rotateX(0deg); z-index: 1; }
  100% { transform: rotateX(-180deg); z-index: 0; }
}

@keyframes countdown-new-flip { 
  0% { transform: rotateX(0deg); z-index: 0; }
  100% { transform: rotateX(-180deg); z-index: 1; }
}

